.ds-ghost:active:not(:disabled) { background: var(--dsw-alias-interactive-bg-active, rgba(255, 255, 255, .14)); }

.ds-host-sample { display: inline-flex; align-items: center; gap: 12px; max-inline-size: 100%; padding: 8px; background: var(--dsw-alias-bg-base, #151517); color: var(--dsw-alias-label-primary, #f9fafb); }
.ds-search { position: relative; display: flex; align-items: center; width: 100%; min-width: 0; color: var(--dsw-alias-label-tertiary, #adb2b8); }
.ds-search-icon { position: absolute; left: 12px; pointer-events: none; }
.ds-search-input { box-sizing: border-box; width: 100%; min-width: 0; height: 36px; padding: 0 34px 0 36px; border: .5px solid var(--dsw-alias-border-l4, rgba(255, 255, 255, .2)); border-radius: var(--dsw-radius-md, 12px); background: var(--dsw-alias-bg-layer-1, #232324); color: var(--dsw-alias-label-primary, #f9fafb); font: 13px/20px system-ui, sans-serif; }
.ds-search-input::placeholder { color: var(--dsw-alias-label-tertiary, #adb2b8); }
.ds-search-input:focus-visible { border-color: var(--dsw-focus-ring-color, var(--dsw-alias-state-business-primary, #7aaaff)); outline: none; box-shadow: 0 0 0 2px color-mix(in srgb, var(--dsw-focus-ring-color, var(--dsw-alias-state-business-primary, #7aaaff)) 18%, transparent); }
@media (pointer: coarse) { .ds-search-input { min-width: 44px; min-height: 44px; } }
@media (forced-colors: active) { .ds-search-input:focus-visible { outline: 2px solid Highlight; outline-offset: 2px; } }

.ds-canvas-nav { display: inline-flex; flex-wrap: wrap; align-items: center; gap: 2px; max-inline-size: 100%; padding: 4px; border: 1px solid #363f4d; border-radius: 10px; background: #171c24; }
.ds-canvas-nav > button { display: grid; place-items: center; inline-size: 34px; min-block-size: 34px; padding: 0; border: 1px solid transparent; border-radius: 6px; background: transparent; color: #c7d0dc; cursor: pointer; }
.ds-canvas-nav > button[aria-pressed=true] { color: #eaf1fd; border-color: #445879; background: #273547; }
.ds-canvas-nav > button:hover:not(:disabled) { background: #263141; }
.ds-canvas-nav > button:focus-visible { outline: 2px solid #a6c7f6; outline-offset: 1px; }
@media (pointer: coarse) { .ds-canvas-nav > button { inline-size: 44px; min-block-size: 44px; } }

.ds-module-states { display: inline-flex; flex-wrap: wrap; align-items: center; gap: 3px 8px; padding: 4px 8px; border: 1px solid #313844; border-radius: 10px; background: #181c23; color: #b5c2d4; font: 12px/18px system-ui, sans-serif; }
.ds-module-state { padding-inline: 6px; border: 1px solid #3c4859; border-radius: 5px; font-size: 11px; }
.ds-module-state[data-enabled=true] { color: #94e1b8; border-color: #355747; }

.ds-action-stage { display: inline-flex; max-inline-size: 100%; box-sizing: border-box; padding: 12px; background: radial-gradient(#343b486b .8px, transparent .8px) 0 0 / 20px 20px #0e1116; color: #e7edf6; }
.ds-action-node { box-sizing: border-box; display: flex; flex-direction: column; align-items: flex-start; justify-content: center; width: 216px; max-width: 100%; min-height: 7rem; padding: .7rem .8rem; border: 1px solid #40516a; border-radius: 10px; background: #192230; color: inherit; text-align: start; cursor: grab; box-shadow: 0 6px 16px #0003; user-select: none; }
.ds-action-node[aria-pressed=true] { border: 2px solid #72aaff; box-shadow: 0 0 0 5px #72aaff18; }
.ds-action-node:focus-visible { outline: 2px solid var(--dsw-alias-state-business-primary, #7aaaff); outline-offset: 2px; }
.ds-action-node:active { cursor: grabbing; }
.ds-action-node small { display: flex; align-items: center; gap: 8px; color: #79d7ae; font: 11px ui-monospace, monospace; }
.ds-action-node small::before { content: ""; inline-size: 8px; block-size: 8px; flex: none; border: 1.5px solid currentColor; border-radius: 2px; }
.ds-action-node strong { margin-block: 6px; font: 700 17px/1.25 system-ui, sans-serif; }
.ds-action-node span { display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 2; line-clamp: 2; overflow: hidden; margin-top: .25rem; color: #9ca7b7; font: 14px/1.4 system-ui, sans-serif; overflow-wrap: anywhere; }

.ds-rule-list { display: flex; flex-direction: column; gap: 4px; min-width: 0; width: min(100%, 17rem); margin: 0; padding: 12px; border: 1px solid #313844; border-radius: 10px; background: #181c23; color: #e7edf6; font: 12px/18px system-ui, sans-serif; list-style: none; box-sizing: border-box; }
.ds-rule-list > li { display: flex; align-items: center; min-inline-size: 0; padding-inline-end: 3px; border: 1px solid #34445e; border-radius: 6px; background: #1c283a; }
.ds-rule-list > li:hover { border-color: #4d6282; }
.ds-rule-list > li:has(.ds-rule-choice[aria-current=true]) { border-color: #7a9ed0; background: #293e5c; }
.ds-rule-choice { display: grid; flex: 1; align-content: center; min-inline-size: 0; min-block-size: 32px; padding: 2px 8px; border: 1px solid transparent; border-radius: 5px; background: transparent; color: inherit; text-align: start; font: inherit; cursor: pointer; }
.ds-rule-choice strong { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 14px; line-height: 20px; font-weight: 600; }
.ds-rule-choice:focus-visible { outline: 2px solid #a6c7f6; outline-offset: -2px; }
@media (pointer: coarse) { .ds-rule-choice { min-block-size: 44px; } }
.ds-move { display: grid; place-items: center; flex: none; inline-size: 27px; block-size: 28px; padding: 0; border: 0; border-radius: 4px; color: #c1d1e9; background: transparent; font: inherit; cursor: pointer; }
.ds-move:hover:not([aria-disabled=true]) { background: #374e70; color: #fff; }
.ds-move[aria-disabled=true] { opacity: .42; cursor: default; }
.ds-move:focus-visible { outline: 2px solid #a6c7f6; outline-offset: -2px; }
@media (pointer: coarse) { .ds-move { min-block-size: 44px; inline-size: 44px; } }

.ds-host-sample { display: inline-flex; align-items: center; gap: 12px; max-inline-size: 100%; padding: 8px; background: var(--dsw-alias-bg-base, #151517); color: var(--dsw-alias-label-primary, #f9fafb); }
.ds-switch { display: inline-flex; flex: 0 0 auto; align-items: center; justify-content: center; width: 36px; height: 20px; padding: 0; border: 0; border-radius: 999px; background: transparent; cursor: pointer; }
.ds-switch-track { box-sizing: border-box; display: block; flex: none; width: 36px; height: 20px; padding: 2px; border-radius: 999px; background: var(--dsw-alias-border-l3, rgba(255, 255, 255, .16)); }
.ds-switch-thumb { display: block; width: 16px; height: 16px; border-radius: 50%; background: var(--dsw-alias-switch-thumb, #adb2b8); transition: transform 120ms ease; }
.ds-switch[aria-checked=true] .ds-switch-track { background: var(--dsw-alias-brand-primary, #f9fafb); }
.ds-switch[aria-checked=true] .ds-switch-thumb { background: var(--dsw-alias-label-primary-foreground, #0f1115); transform: translateX(16px); }
.ds-switch:focus-visible { outline: 2px solid var(--dsw-alias-state-business-primary, #7aaaff); outline-offset: 2px; }
.ds-switch:disabled { cursor: default; opacity: .5; }
@media (prefers-reduced-motion: reduce) { .ds-switch-thumb { transition: none; } }
@media (pointer: coarse) { .ds-switch { min-width: 44px; min-height: 44px; } }
@media (forced-colors: active) { .ds-switch-track { outline: 1px solid ButtonText; } .ds-switch[aria-checked=true] .ds-switch-track { background: Highlight; } .ds-switch-thumb, .ds-switch[aria-checked=true] .ds-switch-thumb { background: ButtonText; } }
